import React, { useState, useEffect } from 'react';
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Wine, TrendingUp, Package, Globe, Leaf } from 'lucide-react';

const API_BASE = 'http://localhost:8000/api';

export default function WineDashboard() {
  const [activeTab, setActiveTab] = useState('comercio');
  const [data, setData] = useState({
    comercio: [],
    producao: [],
    exportacao: [],
    importacao: [],
    processamento: []
  });
  const [stats, setStats] = useState({
    comercioTotal: 0,
    producaoTotal: 0,
    exportacaoTotal: 0,
    comparativo: null
  });
  const [ano, setAno] = useState(2024);
  const [loading, setLoading] = useState(false);
  const [filtro, setFiltro] = useState('');

  const cores = {
    roxo: '#8b5cf6',
    roxoClaro: '#c4b5fd',
    verde: '#22c55e',
    verdeClaro: '#bbf7d0',
    branco: '#ffffff',
    cinza: '#f3f4f6'
  };

  useEffect(() => {
    fetchAllData();
  }, [ano]);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [comRes, prodRes, expRes, impRes, procRes, compRes] = await Promise.all([
        fetch(`${API_BASE}/Comercio/?ano=${ano}`),
        fetch(`${API_BASE}/Producao/?ano=${ano}`),
        fetch(`${API_BASE}/Exportacao/?ano=${ano}`),
        fetch(`${API_BASE}/Importacao/?ano=${ano}`),
        fetch(`${API_BASE}/Processamento/?ano=${ano}`),
        fetch(`${API_BASE}/comparativo/${ano}/`)
      ]);

      const comData = await comRes.json();
      const prodData = await prodRes.json();
      const expData = await expRes.json();
      const impData = await impRes.json();
      const procData = await procRes.json();
      const compData = await compRes.json();

      setData({
        comercio: comData.results || [],
        producao: prodData.results || [],
        exportacao: expData.results || [],
        importacao: impData.results || [],
        processamento: procData.results || []
      });

      setStats({
        comercioTotal: comData.results?.reduce((sum, item) => sum + (item.Quantidade_L || 0), 0) || 0,
        producaoTotal: prodData.results?.reduce((sum, item) => sum + (item.Quantidade_L || 0), 0) || 0,
        exportacaoTotal: expData.results?.reduce((sum, item) => sum + (item.Quantidade_Kg || 0), 0) || 0,
        comparativo: compData
      });
    } catch (err) {
      console.error('Erro ao buscar dados:', err);
    }
    setLoading(false);
  };

  const formatarNumero = (num) => {
    if (num >= 1000000) return (num / 1000000).toFixed(2) + 'M';
    if (num >= 1000) return (num / 1000).toFixed(2) + 'K';
    return num.toFixed(2);
  };

  const processarDadosPorCategoria = (items, chave) => {
    const agrupado = items.reduce((acc, item) => {
      const categoria = item.Categoria || item.Tipo || 'Outro';
      const quantidade = item.Quantidade_L || item.Quantidade_Kg || 0;
      const existing = acc.find(a => a.nome === categoria);
      if (existing) {
        existing.valor += quantidade;
      } else {
        acc.push({ nome: categoria, valor: quantidade });
      }
      return acc;
    }, []);
    return agrupado.sort((a, b) => b.valor - a.valor).slice(0, 8);
  };

  const StatBox = ({ icon: Icon, label, valor, cor }) => (
    <div style={{ backgroundColor: cores.branco, borderLeft: `4px solid ${cor}` }} className="p-6 rounded-lg shadow-md">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-gray-600 text-sm">{label}</p>
          <p style={{ color: cor }} className="text-2xl font-bold mt-2">
            {formatarNumero(valor)}
          </p>
        </div>
        <Icon size={32} style={{ color: cor, opacity: 0.7 }} />
      </div>
    </div>
  );

  const TabButton = ({ id, label }) => (
    <button
      onClick={() => setActiveTab(id)}
      style={{
        backgroundColor: activeTab === id ? cores.roxo : cores.cinza,
        color: activeTab === id ? cores.branco : '#374151'
      }}
      className="px-4 py-2 rounded-lg font-medium transition-all"
    >
      {label}
    </button>
  );

  return (
    <div style={{ backgroundColor: cores.cinza }} className="min-h-screen p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-3 mb-4">
            <Wine size={32} style={{ color: cores.roxo }} />
            <h1 className="text-4xl font-bold" style={{ color: cores.roxo }}>
              Dashboard de Vinhos
            </h1>
          </div>
          <p className="text-gray-600">Análise completa de produção, comercialização e exportação</p>
        </div>

        {/* Filtro de Ano */}
        <div className="mb-6 flex gap-4">
          <input
            type="number"
            value={ano}
            onChange={(e) => setAno(parseInt(e.target.value))}
            className="px-4 py-2 rounded-lg border-2"
            style={{ borderColor: cores.roxo }}
            min="2000"
            max="2030"
          />
          {loading && <p style={{ color: cores.roxo }}>Carregando...</p>}
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
          <StatBox icon={Wine} label="Comercialização" valor={stats.comercioTotal} cor={cores.roxo} />
          <StatBox icon={Package} label="Produção" valor={stats.producaoTotal} cor={cores.verde} />
          <StatBox icon={Globe} label="Exportação" valor={stats.exportacaoTotal} cor={cores.roxoClaro} />
          {stats.comparativo && (
            <StatBox
              icon={TrendingUp}
              label="% Exportado"
              valor={stats.comparativo.percentual_exportado || 0}
              cor={cores.verdeClaro}
            />
          )}
        </div>

        {/* Tabs */}
        <div className="mb-6 flex gap-2 flex-wrap">
          <TabButton id="comercio" label="Comercialização" />
          <TabButton id="producao" label="Produção" />
          <TabButton id="exportacao" label="Exportação" />
          <TabButton id="importacao" label="Importação" />
          <TabButton id="processamento" label="Processamento" />
        </div>

        {/* Gráficos */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
          {/* Gráfico 1: Por Categoria */}
          <div style={{ backgroundColor: cores.branco }} className="p-6 rounded-lg shadow-md">
            <h3 className="text-lg font-bold mb-4" style={{ color: cores.roxo }}>
              Top Categorias
            </h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={processarDadosPorCategoria(data[activeTab], 'nome')}>
                <CartesianGrid stroke={cores.roxoClaro} />
                <XAxis dataKey="nome" angle={-45} textAnchor="end" height={80} />
                <YAxis />
                <Tooltip formatter={(value) => formatarNumero(value)} />
                <Bar dataKey="valor" fill={cores.roxo} radius={[8, 8, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* Gráfico 2: Distribuição */}
          <div style={{ backgroundColor: cores.branco }} className="p-6 rounded-lg shadow-md">
            <h3 className="text-lg font-bold mb-4" style={{ color: cores.verde }}>
              Distribuição por Tipo
            </h3>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={processarDadosPorCategoria(data[activeTab], 'nome').slice(0, 5)}
                  dataKey="valor"
                  nameKey="nome"
                  cx="50%"
                  cy="50%"
                  outerRadius={100}
                  label
                >
                  {[cores.roxo, cores.verde, cores.roxoClaro, cores.verdeClaro, '#a78bfa'].map((cor, idx) => (
                    <Cell key={idx} fill={cor} />
                  ))}
                </Pie>
                <Tooltip formatter={(value) => formatarNumero(value)} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Tabela */}
        <div style={{ backgroundColor: cores.branco }} className="rounded-lg shadow-md overflow-hidden">
          <div className="p-6 border-b-2" style={{ borderColor: cores.roxoClaro }}>
            <h3 className="text-lg font-bold" style={{ color: cores.roxo }}>
              {activeTab === 'comercio' && 'Dados de Comercialização'}
              {activeTab === 'producao' && 'Dados de Produção'}
              {activeTab === 'exportacao' && 'Dados de Exportação'}
              {activeTab === 'importacao' && 'Dados de Importação'}
              {activeTab === 'processamento' && 'Dados de Processamento'}
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr style={{ backgroundColor: cores.cinza }}>
                  <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: cores.roxo }}>
                    Produto/Tipo
                  </th>
                  <th className="px-6 py-3 text-left text-sm font-semibold" style={{ color: cores.roxo }}>
                    {activeTab === 'processamento' ? 'Cultivar' : activeTab === 'exportacao' || activeTab === 'importacao' ? 'País' : 'Categoria'}
                  </th>
                  <th className="px-6 py-3 text-right text-sm font-semibold" style={{ color: cores.roxo }}>
                    Quantidade
                  </th>
                </tr>
              </thead>
              <tbody>
                {data[activeTab].slice(0, 10).map((item, idx) => (
                  <tr key={idx} className="border-b hover:bg-gray-50">
                    <td className="px-6 py-4 text-sm">
                      {item.Produto || item.Tipo || '-'}
                    </td>
                    <td className="px-6 py-4 text-sm">
                      {item.Categoria || item.Países || item.Cultivar || '-'}
                    </td>
                    <td className="px-6 py-4 text-sm text-right font-semibold" style={{ color: cores.verde }}>
                      {formatarNumero(item.Quantidade_L || item.Quantidade_Kg || 0)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-8 text-center text-gray-600 text-sm">
          <p>Dados de {ano} • Atualizado em tempo real</p>
        </div>
      </div>
    </div>
  );
}
